function onlinePCAUpdate(x, state) {
  // x: 120 features, may contain missing
  const z = imputeAndScale(x, state.scaler);
  // Update components via incremental SVD / Oja rule
  state.components = updateBasis(state.components, z, state.learningRate);
  // Update loadings and detect drift
  return state;
}
```

